class Room:
    def __init__(self, name, description, exits, items=None, locked_by=None):
        self.name = name
        self.description = description
        self.exits = exits
        self.items = list(items or [])
        self.locked_by = locked_by

    def describe(self):
        text = f"{self.name}\n{self.description}\nExits: {', '.join(sorted(self.exits))}"
        if self.items:
            text += f"\nYou see: {', '.join(self.items)}"
        return text

